$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
Set-Location $repo
& git fetch origin --prune | Out-Null
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }
$active=@()
foreach($line in @(& git worktree list --porcelain)){ if($line -like 'branch refs/heads/*'){ $active += $line.Substring(18) } }
$deleted=@(); $skipped=@()
function RemoteExists([string]$b){ & git show-ref --verify --quiet ('refs/remotes/origin/'+$b); return ($LASTEXITCODE -eq 0) }
function Delete-Proven([string]$b,[string]$proof){
  if(-not (RemoteExists $b)){ return }
  if($active -contains $b){ $script:skipped += [ordered]@{branch=$b;reason='active-worktree'}; return }
  & git push origin --delete $b | Out-Null
  if($LASTEXITCODE -ne 0){ throw ('delete failed: '+$b) }
  $script:deleted += [ordered]@{branch=$b;proof=$proof}
}
# Smart Pack temp branch: all three substantive files are already byte-identical on main.
$smart='integration/smart-pack-planner-main-20260929'
if(RemoteExists $smart){
  $paths=@('src/MhwModManager.Core/SmartPackPlanner.cs','tests/MhwModManager.Tests/SmartPackPlannerTests.cs','_AGENT_CONTEXT/SMART_PACK_PLANNER_AUDIT.md')
  $ok=$true
  foreach($p in $paths){
    $a=(& git rev-parse ('origin/main:'+ $p)).Trim()
    $b=(& git rev-parse ('origin/'+$smart+':'+ $p)).Trim()
    if($a -ne $b){$ok=$false}
  }
  if($ok){ Delete-Proven $smart 'substantive-files-identical-to-main' } else {$skipped += [ordered]@{branch=$smart;reason='smart-pack-file-mismatch'}}
}
# Original Smart Pack branch: preserve implementation/tests/audit already on main; remaining delta is stale continuity bookkeeping.
$oldSmart='agent/smart-pack-planner-core'
if(RemoteExists $oldSmart){
  $paths=@('src/MhwModManager.Core/SmartPackPlanner.cs','tests/MhwModManager.Tests/SmartPackPlannerTests.cs','_AGENT_CONTEXT/SMART_PACK_PLANNER_AUDIT.md')
  $ok=$true
  foreach($p in $paths){
    $a=(& git rev-parse ('origin/main:'+ $p)).Trim()
    $b=(& git rev-parse ('origin/'+$oldSmart+':'+ $p)).Trim()
    if($a -ne $b){$ok=$false}
  }
  if($ok){ Delete-Proven $oldSmart 'useful-smart-pack-files-identical-to-main;remaining-context-stale' } else {$skipped += [ordered]@{branch=$oldSmart;reason='smart-pack-file-mismatch'}}
}
# Closed diagnostic PR explicitly marked do-not-merge.
Delete-Proven 'agent/heaven-hosted-runner-diagnose-20260929' 'closed-diagnostic-pr-do-not-merge'
# Proven supersession chains from Git ancestry.
$pairs=@(
 @('ui/frontend-ux-overhaul','ui/frontend-responsive-polish-20260928'),
 @('agent/updater-existing-release-rest-ref-gate-20260928','agent/updater-existing-release-rest-ref-gate2-20260928')
)
foreach($pair in $pairs){
  $old=$pair[0]; $new=$pair[1]
  if((RemoteExists $old) -and (RemoteExists $new)){
    & git merge-base --is-ancestor ('origin/'+$old) ('origin/'+$new)
    if($LASTEXITCODE -eq 0){ Delete-Proven $old ('ancestor-of-'+$new) } else {$skipped += [ordered]@{branch=$old;reason='not-ancestor-of-newer'}}
  }
}
& git fetch origin --prune | Out-Null
[ordered]@{main=(& git rev-parse origin/main).Trim();deleted=$deleted;skipped=$skipped;active=$active} | ConvertTo-Json -Depth 6
